// ====== DEMO CONFIG – move these to n8n Credentials / Variables before production ======
return [{
  json: {
    SUPABASE_URL: "https://YOUR-PROJECT.supabase.co",
    SUPABASE_SERVICE_KEY: "YOUR-SERVICE-ROLE-KEY",      // server-side only, never in the dashboard
    TEAMS_WEBHOOK: "https://YOUR-TENANT.webhook.office.com/webhookb2/....",
    DASHBOARD_URL: "https://your-dashboard-url/",      // shown at the bottom of Teams cards

    // Vendors/products in client environments. Case-insensitive substring match on
    // vendorProject + product (KEV) and title + summary (news).
    VENDOR_ALLOWLIST: [
      "Microsoft","Windows","Exchange","SharePoint","Office","Entra","Azure","Intune",
      "Fortinet","FortiGate","FortiOS","FortiManager","FortiAnalyzer","FortiClient",
      "ConnectWise","ScreenConnect","NinjaOne","Ninja RMM",
      "Cisco","Ivanti","Citrix","NetScaler","VMware","Broadcom","Veeam","SonicWall",
      "Palo Alto","PAN-OS","GlobalProtect","Apple","iOS","macOS","Google","Chrome","Chromium",
      "Mozilla","Firefox","Adobe","Acrobat","Atlassian","Confluence","Jira","Oracle",
      "SolarWinds","Zoho","ManageEngine","Synology","QNAP","Ubiquiti","UniFi",
      "Dell","Lenovo","Progress","MOVEit","GitLab","Jenkins","OpenSSL","Linux","Ubuntu",
      "Samba","PaperCut","Kaseya","CrowdStrike","Proofpoint","ThreatLocker","7-Zip","WinRAR",
      "Auvik","Proxmox","Hyper-V","SQL Server","Teams","OneDrive","Outlook","Defender"
    ],

    // High-signal phrases for news scoring (weight added to score)
    SIGNAL_TERMS: {
      "zero-day": 3, "0-day": 3, "actively exploited": 3, "in the wild": 3,
      "exploited": 2, "ransomware": 2, "critical": 1, "rce": 2, "remote code execution": 2,
      "authentication bypass": 2, "patch now": 2, "emergency": 2, "out-of-band": 2,
      "cve-": 1, "australia": 2, "australian": 2, "msp": 2, "mssp": 2, "rmm": 2,
      "supply chain": 1, "phishing": 1, "data breach": 1
    },
    MIN_SCORE: 3,                 // article is "relevant" at or above this
    KEV_LOOKBACK_DAYS: 14,        // on first run, only notify about KEV entries this recent
    AI_ENABLED: false             // flip to true once ANTHROPIC key is set in the AI node
  }
}];

const cfg = $('Config').first().json;
const allow = cfg.VENDOR_ALLOWLIST.map(s => s.toLowerCase());
const catalog = $input.first().json;
const vulns = catalog.vulnerabilities || [];

const rows = [];
for (const v of vulns) {
  const hay = `${v.vendorProject} ${v.product}`.toLowerCase();
  const hit = allow.find(a => hay.includes(a));
  if (!hit) continue;
  rows.push({
    cve_id: v.cveID,
    vendor: v.vendorProject,
    product: v.product,
    vuln_name: v.vulnerabilityName,
    description: v.shortDescription,
    required_action: v.requiredAction,
    date_added: v.dateAdded,
    due_date: v.dueDate,
    ransomware: v.knownRansomwareCampaignUse || 'Unknown',
    matched_vendor: hit,
    catalog_version: catalog.catalogVersion,
  });
}
return [{ json: { rows, total_in_catalog: vulns.length, in_scope: rows.length } }];

// Supabase returned ONLY the rows it inserted (Prefer: resolution=ignore-duplicates,return=representation)
const cfg = $('Config').first().json;
const inserted = $input.all().map(i => i.json).filter(r => r && r.cve_id);
const cutoff = new Date(Date.now() - cfg.KEV_LOOKBACK_DAYS * 86400000);
const fresh = inserted.filter(r => new Date(r.date_added) >= cutoff)
                      .sort((a, b) => (a.date_added < b.date_added ? 1 : -1));
if (fresh.length === 0) return [];

const body = [
  { type: 'TextBlock', size: 'Large', weight: 'Bolder',
    text: `CISA KEV – ${fresh.length} new in-scope ${fresh.length === 1 ? 'entry' : 'entries'}` },
  { type: 'TextBlock', isSubtle: true, spacing: 'None',
    text: `Filtered to vendors in our client environments · ${inserted.length} stored this run` },
];
for (const r of fresh.slice(0, 15)) {
  const flag = r.ransomware === 'Known' ? ' ⚠ **Ransomware use known**' : '';
  body.push({ type: 'TextBlock', weight: 'Bolder', spacing: 'Medium', wrap: true,
    text: `[${r.cve_id}](https://nvd.nist.gov/vuln/detail/${r.cve_id}) – ${r.vendor} ${r.product}${flag}` });
  body.push({ type: 'TextBlock', wrap: true, spacing: 'None', text: r.vuln_name });
  body.push({ type: 'TextBlock', wrap: true, spacing: 'None', isSubtle: true,
    text: `Added ${r.date_added} · Federal due ${r.due_date} · ${r.required_action}` });
}
if (fresh.length > 15) body.push({ type: 'TextBlock', isSubtle: true, text: `…and ${fresh.length - 15} more on the dashboard` });
body.push({ type: 'TextBlock', spacing: 'Medium', text: `[Open dashboard](${cfg.DASHBOARD_URL})` });

return [{ json: { card: body, count: fresh.length, cves: fresh.map(r => r.cve_id) } }];
